"""

from __future__ import annotations

import json
import os
from typing import Any


# ---------------------------------------------------------------------------
# UIE JSON schema for XGrammar constrained decoding
# ---------------------------------------------------------------------------

UIE_JSON_SCHEMA: dict[str, Any] = {
    "type": "object",
    "properties": {
        "entities": {
